from bisect import bisect_left

def insert_point(a, x):
    return bisect_left(a, x)

assert insert_point([1, 3, 3, 5, 7], 3) == 1
assert insert_point([1, 3, 3, 5, 7], 4) == 3
assert insert_point([], 1) == 0

