test "t01 bisect_left" {
    const a = [_]i32{ 1, 3, 3, 5, 7 };
    try std.testing.expectEqual(@as(usize, 0), bisectLeft(&a, 0));
    try std.testing.expectEqual(@as(usize, 1), bisectLeft(&a, 3));
    try std.testing.expectEqual(@as(usize, 3), bisectLeft(&a, 4));
    try std.testing.expectEqual(@as(usize, 5), bisectLeft(&a, 9));
    const empty = [_]i32{};
    try std.testing.expectEqual(@as(usize, 0), bisectLeft(&empty, 1));
}
